use axum::{
    extract::{Path, State},
    http::StatusCode,
    routing::{delete, get},
    Json, Router,
};
use serde::{Deserialize, Serialize};
use std::sync::{Arc, Mutex};

#[derive(Clone, Serialize)]
struct Todo {
    id: i32,
    title: String,
}

#[derive(Deserialize)]
struct CreateTodo {
    title: String,
}

struct AppState {
    todos: Vec<Todo>,
    next_id: i32,
}

type Shared = Arc<Mutex<AppState>>;

async fn list_todos(State(state): State<Shared>) -> Json<Vec<Todo>> {
    let state = state.lock().unwrap();
    Json(state.todos.clone())
}

async fn create_todo(
    State(state): State<Shared>,
    Json(payload): Json<CreateTodo>,
) -> (StatusCode, Json<Todo>) {
    let mut state = state.lock().unwrap();
    let id = state.next_id;
    state.next_id += 1;
    let todo = Todo { id, title: payload.title };
    state.todos.push(todo.clone());
    (StatusCode::CREATED, Json(todo))
}

async fn delete_todo(State(state): State<Shared>, Path(id): Path<i32>) -> StatusCode {
    let mut state = state.lock().unwrap();
    let before = state.todos.len();
    state.todos.retain(|t| t.id != id);
    if state.todos.len() < before {
        StatusCode::NO_CONTENT
    } else {
        StatusCode::NOT_FOUND
    }
}

#[tokio::main]
async fn main() {
    let state: Shared = Arc::new(Mutex::new(AppState {
        todos: Vec::new(),
        next_id: 1,
    }));
    let app = Router::new()
        .route("/todos", get(list_todos).post(create_todo))
        .route("/todos/:id", delete(delete_todo))
        .with_state(state);
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8041").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
